#!/bin/sh
# Cloud Vault brand step. Sourced by init.sh (before exec /start.sh) and by the
# per-service test (test-cloud-vault-brand.sh) with WV/OUT/SRC pointed at a fixture.
#
# WHY: the upstream web vault says "Vaultwarden Web" / Bitwarden everywhere and the
# owner once could not tell this vault from a stranger's public Vaultwarden. This
# builds a branded COPY-OF-REFERENCES of /web-vault in tmpfs (symlinks for everything
# untouched; real copies only of index.html, images, en locale, main.js, manifests) and
# points WEB_VAULT_FOLDER at it. The image, the API and the client protocol are not
# touched. Server-side CSS/admin/email branding comes from TEMPLATES_FOLDER=/config/brand.
#
# FAILSAFE: any failure removes the partial tree and leaves WEB_VAULT_FOLDER unset
# (stock web vault) — a branding bug can never take the vault offline.
WV="${WV:-/web-vault}"
OUT="${OUT:-/tmp/web-vault-cloud-vault}"
SRC="${SRC:-/config/brand}"

cv_brand() {
  set -eu
  rm -rf "$OUT"
  mkdir -p "$OUT/app" "$OUT/locales"

  # 1. Symlink farm: every top-level entry, then replace the ones we patch.
  for e in "$WV"/* "$WV"/.[!.]*; do
    [ -e "$e" ] || continue
    n=$(basename "$e")
    case "$n" in
      index.html|images|locales|app) continue ;;
    esac
    # JSON manifests that carry the upstream name are patched copies, rest are links.
    if [ -f "$e" ] && case "$n" in *.json) grep -q "Vaultwarden" "$e" ;; *) false ;; esac; then
      sed -e 's/Vaultwarden Web/Cloud Vault/g' -e 's/"theme_color": *"#FFFFFF"/"theme_color": "#00BFA5"/' \
          -e 's/"background_color": *"#FFFFFF"/"background_color": "#0A0A0A"/' "$e" > "$OUT/$n"
    else
      ln -s "$e" "$OUT/$n"
    fi
  done

  # 2. app/: link all, copy+patch only the main bundle (display strings, never identifiers).
  for f in "$WV"/app/*; do
    n=$(basename "$f")
    case "$n" in
      main.*.js)
        sed -e 's/Vaultwarden Web/Cloud Vault/g' \
            -e 's/"alt","Vaultwarden"/"alt","Cloud Vault"/g' \
            -e 's/"alt","Bitwarden"/"alt","Cloud Vault"/g' \
            -e 's/A modified version of the Bitwarden® Web Vault for Vaultwarden (an unofficial rewrite of the Bitwarden® server)\./Cloud Vault: a private, self-hosted password vault./g' \
            -e 's/Vaultwarden is not associated with the Bitwarden® project nor Bitwarden Inc\./Cloud Vault is a private service./g' \
            "$f" > "$OUT/app/$n" ;;
      *) ln -s "$f" "$OUT/app/$n" ;;
    esac
  done

  # 3. locales: link all languages, patch the English one (display text only).
  for d in "$WV"/locales/*; do
    n=$(basename "$d")
    if [ "$n" = "en" ]; then
      mkdir -p "$OUT/locales/en"
      sed -e 's/Bitwarden®/Cloud Vault/g' -e 's/Bitwarden/Cloud Vault/g' -e 's/Vaultwarden/Cloud Vault/g' \
          "$d/messages.json" > "$OUT/locales/en/messages.json"
    else
      ln -s "$d" "$OUT/locales/$n"
    fi
  done

  # 4. images: copy, then overwrite with the Cloud Vault artwork.
  cp -r "$WV/images" "$OUT/images"
  chmod -R u+w "$OUT/images"
  cp "$SRC/icon.svg"       "$OUT/images/cloud-vault.svg"
  cp "$SRC/icon.svg"       "$OUT/images/icon-white.svg"
  cp "$SRC/icon.svg"       "$OUT/images/safari-pinned-tab.svg"
  cp "$SRC/icon.svg"       "$OUT/images/icons/safari-pinned-tab.svg" 2>/dev/null || true
  cp "$SRC/logo.svg"       "$OUT/images/logo.svg"
  cp "$SRC/logo-white.svg" "$OUT/images/logo-white.svg"
  put() { base64 -d "$SRC/i$1.png.b64" > "$OUT/images/$2"; }
  put 16  favicon-16x16.png
  put 32  favicon-32x32.png
  put 150 mstile-150x150.png
  put 180 apple-touch-icon.png
  put 192 android-chrome-192x192.png
  put 512 android-chrome-512x512.png
  put 192 logo-dark@2x.png
  put 192 logo-white@2x.png
  for p in favicon-16x16.png favicon-32x32.png mstile-150x150.png apple-touch-icon.png android-chrome-192x192.png android-chrome-512x512.png; do
    [ -f "$OUT/images/icons/$p" ] && cp "$OUT/images/$p" "$OUT/images/icons/$p"
  done

  # 5. index.html: title, alt text, accent, favicon links carrying the icon hash.
  H=$(sha256sum "$SRC/icon.svg" | cut -c1-12)
  sed -e 's|<title page-title>Vaultwarden Web</title>|<title page-title>Cloud Vault</title>|' \
      -e 's|alt="Vaultwarden"|alt="Cloud Vault"|g' \
      -e 's|#175DDC|#00BFA5|g' \
      -e "s|<link rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"images/favicon-32x32.png\"/>|<link rel=\"icon\" type=\"image/svg+xml\" href=\"images/cloud-vault.svg?v=$H\"/><link rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"images/favicon-32x32.png?v=$H\"/>|" \
      -e "s|href=\"images/favicon-16x16.png\"|href=\"images/favicon-16x16.png?v=$H\"|" \
      -e "s|href=\"images/safari-pinned-tab.svg\"|href=\"images/safari-pinned-tab.svg?v=$H\"|" \
      "$WV/index.html" > "$OUT/index.html"
  grep -q "Cloud Vault" "$OUT/index.html"
  grep -q "cloud-vault.svg?v=$H" "$OUT/index.html"
}

if ( cv_brand ) >/dev/null 2>&1; then
  export WEB_VAULT_FOLDER="$OUT"
  echo "[cloud-vault] brand applied: WEB_VAULT_FOLDER=$OUT"
else
  rm -rf "$OUT"
  echo "[cloud-vault] WARNING: brand step failed (non-fatal) — serving stock web vault"
fi
